		if num == target {
			return i
		}
	}
	return -1
}

func main() {
	var n int
	fmt.Scan(&n)
	nums := make([]int, n)
	for i := range nums {
		fmt.Scan(&nums[i])
	}
	var target int
	fmt.Scan(&target)
	fmt.Println(findIndex(nums, target))
}
